sources.python/upper.py:
from rows import initial


def upper(rows):
    best = initial(rows)
    for candidate in rows:
        if candidate["score"] > best["score"]:
            best = candidate
    return best["ticket"]

sources.python/lower.py:
from rows import initial


def lower(rows):
    best = initial(rows)
    for candidate in rows:
        if candidate["score"] < best["score"]:
            best = candidate
    return best["ticket"]

