from upper import upper
from lower import lower


def ranking(rows):
    return {"high": upper(rows), "low": lower(rows)}


def main(batches):
    return [ranking(batch) for batch in batches]

sources.python/debit.py:
from amounts import cents


def debit(readings):
    return sum(cents(item["bought"]) for item in readings)

sources.python/credit.py:
from amounts import cents


def credit(readings):
    return sum(cents(item["sold"]) for item in readings)

