sources.python/profile.py:
from samples import Edge


def profile(edges: list[Edge]):
    ascent = descent = 0
    for edge in edges:
        if edge.valid and edge.change > 0:
            ascent += edge.change
        if edge.change < 0:
            descent -= edge.change
    return {"ascent": ascent, "descent": descent}
